// Every public/ asset URL goes through assetUrl(). A production build resolves the content-hashed
// published name from the manifest generated by scripts/build-asset-manifest.mjs; a path that is
// not in the manifest throws instead of falling back to the unhashed name. The development server
// (and Node, where import.meta.env is undefined) serves public/ directly under the original paths.
const production = import.meta.env?.PROD === true;
const manifest = production
  ? Object.values(import.meta.glob('../content/asset-manifest.json', { eager: true, import: 'default' }))[0]
  : undefined;

// Accepts 'art/x.webp', './art/x.webp' or 'public/art/x.webp'.
export const normalizeAssetPath = (path) => path.replace(/^(?:\.\/)?(?:public\/)?/, '');

let base;
const resolved = new Map();

export function assetUrl(path) {
  const current = document.baseURI;
  if (current !== base) {
    base = current;
    resolved.clear();
  }
  let href = resolved.get(path);
  if (href === undefined) {
    const key = normalizeAssetPath(path);
    const published = !production ? key : manifest && Object.hasOwn(manifest, key) ? manifest[key] : undefined;
    if (!published) throw new Error('静态资源不在发布清单中：' + key);
    href = new URL('./' + published, current).href;
    resolved.set(path, href);
  }
  return href;
}

// A hashed asset that fails to load may belong to a replaced build. main.js registers the
// production update check here; without a listener (development, no service worker) it is a no-op.
let failureListener;
export function onAssetLoadFailure(listener) {
  failureListener = listener;
}
export function reportAssetLoadFailure() {
  failureListener?.();
}
